    key,
    map: new Map()
  });

  if (state.key !== key) {
    setState({
      key,
      map: new Map()
    });
  }

  const { map } = state;

  const getAverageRowHeight = useCallback(() => {
    let totalHeight = 0;

    map.forEach((height) => {
      totalHeight += height;
